import {useEffect,useId,useRef,useState} from 'react';
import './palette.css';
// No package manifest, exports, or catalog was supplied, so available package
// capabilities cannot honestly be checked. This fallback uses React and native
// dialog semantics only; it assumes no undocumented design-system exports.
export type Command={id:string;label:string;group:string;run:()=>void};
export function CommandPalette({open,onClose,commands,recentIds,onRecentChange}:{open:boolean;onClose:()=>void;commands:readonly Command[];recentIds:readonly string[];onRecentChange:(ids:string[])=>void}){
 const dialog=useRef<HTMLDialogElement>(null),search=useRef<HTMLInputElement>(null),id=useId();
 const [query,setQuery]=useState(''),[active,setActive]=useState(0);
 const matches=commands.filter(c=>c.label.toLocaleLowerCase().includes(query.toLocaleLowerCase().trim()));
 const recent=!query.trim()?recentIds.map(key=>matches.find(c=>c.id===key)).filter((c):c is Command=>!!c):[];
 const sections=[...(recent.length?[{label:'Recent',items:recent}]:[]),...Array.from(new Set(matches.map(c=>c.group))).map(group=>({label:group,items:matches.filter(c=>c.group===group&&!recent.some(r=>r.id===c.id))})).filter(g=>g.items.length)];
 const results=sections.flatMap(g=>g.items);const selected=Math.min(active,results.length-1);
 useEffect(()=>{const node=dialog.current;if(!node)return;if(open){const prior=document.activeElement as HTMLElement|null;setQuery('');setActive(0);node.showModal();search.current?.focus();return()=>{node.close();prior?.focus()}}},[open]);
 useEffect(()=>{if(open&&selected>=0)document.getElementById(id+'-option-'+selected)?.scrollIntoView({block:'nearest'})},[selected,open,id,query]);
 function execute(command:Command){onRecentChange([command.id,...recentIds.filter(x=>x!==command.id)].slice(0,10));onClose();command.run()}
 return <dialog ref={dialog} className="command-palette" aria-labelledby={id+'-title'} onCancel={e=>{e.preventDefault();onClose()}}>
 <header><h2 id={id+'-title'}>Commands</h2><button onClick={onClose} aria-label="Close command palette">Close</button></header>
 <label htmlFor={id+'-search'}>Search commands</label>
 <input ref={search} id={id+'-search'} role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls={id+'-results'} aria-activedescendant={selected>=0?id+'-option-'+selected:undefined} value={query} onChange={e=>{setQuery(e.target.value);setActive(0)}} onKeyDown={e=>{
 if(e.key==='ArrowDown'){e.preventDefault();setActive(i=>results.length?(i+1)%results.length:0)}
 else if(e.key==='ArrowUp'){e.preventDefault();setActive(i=>results.length?(i+results.length-1)%results.length:0)}
 else if(e.key==='Enter'&&results[selected]){e.preventDefault();execute(results[selected])}
 }}/>
 <div id={id+'-results'} role="listbox" aria-label="Commands">{sections.map((group,groupIndex)=><div key={groupIndex} role="group" aria-labelledby={id+'-group-'+groupIndex}><h3 id={id+'-group-'+groupIndex}>{group.label}</h3>{group.items.map(command=>{const index=results.indexOf(command);return <div key={command.id} id={id+'-option-'+index} role="option" aria-selected={index===selected} onPointerDown={e=>e.preventDefault()} onClick={()=>execute(command)}>{command.label}</div>})}</div>)}</div>
 {results.length===0&&<p role="status">No commands match “{query}”. Try another search.</p>}
 </dialog>;
}
// The application owns command registration, permissions, and persistence of recentIds.
